import { afterEach, describe, expect, it, vi } from "vitest";
// The payloads cxp-api serializes (generated by the Rust test `wire_fixture`).
import wire from "../../../../../crates/cxp-api/tests/fixtures/wire.json";
import { applicationsApi } from "./applications";
import { componentsApi } from "./components";
import { customersApi } from "./customers";
import { feedbackApi } from "./feedback";
import { pagesApi } from "./pages";
import { surveysApi } from "./surveys";
import { ticketsApi } from "./tickets";

// The server ignores keys it does not know and still accepts the old
// snake_case spellings (#24), so a mistyped or stale key here would pass every
// other test while silently dropping a filter or a field. These pin the exact
// camelCase names the console sends.

const ID = "00000000-0000-0000-0000-000000000001";

function record(body: unknown = {}) {
  const calls: { url: URL; body: unknown }[] = [];
  vi.stubGlobal(
    "fetch",
    vi.fn(async (input: string, init?: RequestInit) => {
      calls.push({
        url: new URL(input, "http://console.test"),
        body: init?.body ? JSON.parse(String(init.body)) : undefined,
      });
      return new Response(JSON.stringify(body), { status: 200 });
    }),
  );
  return calls;
}

function queryKeys(url: URL) {
  return [...url.searchParams.keys()].sort();
}

const catalog = { experienceId: ID, applicationId: ID, pageId: ID, componentId: ID };
const catalogKeys = ["applicationId", "componentId", "experienceId", "pageId"];

describe("the console sends camelCase keys", () => {
  afterEach(() => vi.unstubAllGlobals());

  it("in list query strings", async () => {
    const calls = record({ data: [], total: 0, limit: 50, offset: 0 });
    await customersApi.list(catalog);
    await surveysApi.list(catalog);
    await ticketsApi.list({ ...catalog, customerId: ID, status: "open", priority: "high" });
    await feedbackApi.list({ ...catalog, customerId: ID, feedbackType: "nps" });
    await applicationsApi.list({ experienceId: ID });
    await pagesApi.list({ applicationId: ID });
    await componentsApi.list({ pageId: ID });

    const page = ["limit", "offset"];
    expect(calls.map((c) => queryKeys(c.url))).toEqual([
      [...catalogKeys, ...page].sort(),
      [...catalogKeys, ...page].sort(),
      [...catalogKeys, ...page, "customerId", "priority", "status"].sort(),
      [...catalogKeys, ...page, "customerId", "feedbackType"].sort(),
      ["experienceId", ...page].sort(),
      ["applicationId", ...page].sort(),
      ["pageId", ...page].sort(),
    ]);
  });

  it("in request bodies", async () => {
    const calls = record(wire.ticket);
    await ticketsApi.create({ customerId: ID, subject: "s" });
    await ticketsApi.update(ID, { assignedTo: "grace" });
    await applicationsApi.create({ experienceId: ID, teamId: ID, name: "a" });
    await pagesApi.create({ applicationId: ID, teamId: ID, name: "p" });
    await componentsApi.create({ pageId: ID, teamId: ID, name: "c", componentType: "button" });
    await componentsApi.update(ID, { componentType: "link", teamId: null });

    expect(calls.map((c) => Object.keys(c.body as object).sort())).toEqual([
      ["customerId", "subject"],
      ["assignedTo"],
      ["experienceId", "name", "teamId"],
      ["applicationId", "name", "teamId"],
      ["componentType", "name", "pageId", "teamId"],
      ["componentType", "teamId"],
    ]);
  });

  it("and reads search from the capped list envelope", async () => {
    record(wire.customerSearch);
    const found = await customersApi.search("ada");
    expect(found.totalCapped).toBe(false);
    expect(found.data[0].email).toBe(wire.customer.email);
  });
});
